==== DeriveHouseholdId ====
package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;

/**
 * Runs in the create-owner pipeline before {@link EnsureUniqueIdentity} and {@link BuildOwner}.
 * Computes the deterministic {@code householdId} — the first 12 hex characters of SHA-256 over the
 * owner's normalized lastName and postcode (see {@link HouseholdId#compute}) — and publishes it as
 * an {@link Out} so {@link EnsureUniqueIdentity} can key duplicate detection on it and
 * {@link AssignHousehold} can stamp it onto the owner being created.
 *
 * <p>Because the identifier is derived from {@code (lastName, postcode)}, owners with the same
 * lastName and postcode share it automatically — no owner has to opt in. {@code sharesHousehold} no
 * longer forms the link; it only bypasses the household duplicate block in
 * {@link EnsureUniqueIdentity}. An owner with no postcode has no shared household, so {@code null}
 * is published and its identityKey carries an empty household component.
 */
public class DeriveHouseholdId {

    public void service(@Val OwnerFieldsDto request, Out<HouseholdId> householdIdOut) {
        String householdId = HouseholdId.compute(request.getLastName(), request.getPostcode());
        householdIdOut.set(householdId == null ? null : new HouseholdId(householdId));
    }
}

==== EnsureUniqueIdentity ====
package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.escalation.DuplicateIdentityException;

/**
 * The single duplicate-detection step in the create-owner pipeline, consolidating what used to be
 * separate telephone, email and household checks. Runs after the telephone and email are normalized
 * and after {@link DeriveHouseholdId} has resolved any shared {@code householdId}.
 *
 * <p>It applies two 409 rules against the already-stored owners:
 * <ul>
 * <li><b>Identity duplicate</b> — the request's {@code identityKey}, derived exactly as
 * {@link Owner#getIdentityKey()} does ({@code normalizedTelephone|email|householdId}, email and
 * householdId empty when absent), equals an existing owner's whole key. This always rejects, even
 * with {@code sharesHousehold}.</li>
 * <li><b>Household duplicate</b> — the request's computed {@code householdId} (from lastName and
 * postcode) matches an existing owner's. Because the household is keyed on {@code (lastName,
 * postcode)}, a second owner in that household is a duplicate <em>unless</em> it declares
 * {@code sharesHousehold}, which admits it as a member.</li>
 * </ul>
 */
public class EnsureUniqueIdentity {

    public void service(@Val OwnerFieldsDto request, @Val HouseholdId householdId,
            OwnerRepository ownerRepository) throws DuplicateIdentityException {
        String householdIdValue = (householdId == null) ? null : householdId.value();
        String identityKey = identityKey(request, householdIdValue);
        boolean sharesHousehold = Boolean.TRUE.equals(request.getSharesHousehold());
        for (Owner existing : ownerRepository.findAll()) {
            if (identityKey.equals(existing.getIdentityKey())) {
                throw new DuplicateIdentityException(identityKey);
            }
            // A household of one (no postcode) shares with no one; sharesHousehold admits a member.
            if (!sharesHousehold && householdIdValue != null
                    && householdIdValue.equals(existing.getHouseholdId())) {
                throw new DuplicateIdentityException(householdIdValue);
            }
        }
    }

    /** Derive the key for the owner being created, matching {@link Owner#getIdentityKey()} exactly. */
    private static String identityKey(OwnerFieldsDto request, String householdId) {
        String tel = request.getTelephone() == null ? "" : request.getTelephone();
        String email = request.getEmail();
        String mail = (email == null || email.isBlank()) ? "" : email;
        String household = (householdId == null || householdId.isBlank()) ? "" : householdId;
        return tel + "|" + mail + "|" + household;
    }
}

==== EnsureCityCapacity ====
package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.repository.OwnerRepository;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.escalation.CityAtCapacityException;

/**
 * Runs in the create-owner pipeline before {@link BuildOwner}. Counts existing owners whose city
 * matches the request's city (case-insensitively) and rejects the request with a 409 when that
 * count has already reached the per-city capacity of 50, so a full city cannot register any further
 * owners.
 */
public class EnsureCityCapacity {

    private static final int CAPACITY = 50;

    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
            throws CityAtCapacityException {
        String city = request.getCity();
        long count = ownerRepository.findAll().stream()
                .filter(existing -> city.equalsIgnoreCase(existing.getCity()))
                .count();
        if (count >= CAPACITY) {
            throw new CityAtCapacityException(city, (int) count);
        }
    }
}

==== EnsureDailyOwnerLimit ====
package org.springframework.samples.petclinic.rest.function.owner;

import java.time.LocalDate;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.repository.OwnerRepository;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.escalation.DailyOwnerLimitException;

/**
 * Runs in the create-owner pipeline before {@link BuildOwner}. The daily limit is counted per
 * business day: the incoming request's effective registration date — the value it supplied, or the
 * server's current date when omitted — is adjusted to a business day via {@link BusinessDays}
 * (a weekend rolls forward to the next Monday), matching what {@link DefaultOwnerRegistrationDate}
 * will store. Counts existing owners already registered on that adjusted business day and rejects
 * the request with a 429 once that count has reached the daily limit of 100, so no further owners
 * can be created for that business day once the limit is hit.
 */
public class EnsureDailyOwnerLimit {

    private static final int DAILY_LIMIT = 100;

    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
            throws DailyOwnerLimitException {
        LocalDate supplied = request.getRegistrationDate();
        LocalDate businessDay = BusinessDays.adjust(supplied != null ? supplied : LocalDate.now());
        long count = ownerRepository.findAll().stream()
                .filter(existing -> businessDay.equals(existing.getRegistrationDate()))
                .count();
        if (count >= DAILY_LIMIT) {
            throw new DailyOwnerLimitException((int) count);
        }
    }
}

