48	package org.springframework.samples.petclinic.rest.function.owner;
49	
50	import net.officefloor.plugin.variable.Val;
51	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
52	import org.springframework.samples.petclinic.rest.escalation.InvalidTelephoneException;
53	
54	/**
55	 * Runs after {@link ValidateOwnerFields} and before {@link BuildOwner} in the create-owner
56	 * pipeline. Normalizes the telephone into E.164 form and mutates the validated body in place so
57	 * later steps build, compare and store the normalized value.
58	 *
59	 * <p>Rules: strip spaces, dashes and brackets. A leading {@code '+'} keeps its country code as
60	 * given; otherwise country code {@code '+61'} is assumed and a single leading {@code '0'} is
61	 * dropped from the national digits. The result must be 8 to 15 digits after the {@code '+'};
62	 * anything else (or any leftover non-digit) is rejected with a 400. So {@code '0412 345 678'} is
63	 * stored as {@code '+61412345678'}.
64	 *
65	 * <p>Known country codes additionally fix the national-number length: {@code '+61'} requires 9
66	 * national digits and {@code '+1'} requires 10. A number whose national part is the wrong length
67	 * for its country code is rejected with a 400. Other country codes carry no length rule.
68	 */
69	public class NormalizeOwnerTelephone {
70	
71	    public void service(@Val OwnerFieldsDto request) throws InvalidTelephoneException {
72	        String raw = request.getTelephone();
73	        request.setTelephone(toE164(raw));
74	    }
75	
76	    private static String toE164(String raw) throws InvalidTelephoneException {
77	        if (raw == null) {
78	            throw new InvalidTelephoneException(raw);
79	        }
80	        String trimmed = raw.trim();
81	        boolean hasCountryCode = trimmed.startsWith("+");
82	        // Strip formatting: spaces, dashes and brackets.
83	        String cleaned = trimmed.replaceAll("[\\s\\-()]", "");
84	
85	        String digits;
86	        if (hasCountryCode) {
87	            digits = cleaned.substring(1); // drop the leading '+', keep the country code
88	        } else {
89	            String national = cleaned;
90	            if (national.startsWith("0")) {
91	                national = national.substring(1); // drop a single leading national-trunk '0'
92	            }
93	            digits = "61" + national; // assume Australian country code
94	        }
95	
96	        if (!digits.matches("\\d{8,15}")) {
97	            throw new InvalidTelephoneException(raw);
98	        }
99	        requireNationalLength(digits, raw);
100	        return "+" + digits;
101	    }
102	
103	    /**
104	     * Enforces the national-number length for country codes that fix it: {@code '61'} requires 9
105	     * national digits, {@code '1'} requires 10. Country codes without a rule pass through.
106	     */
107	    private static void requireNationalLength(String digits, String raw)
108	            throws InvalidTelephoneException {
109	        int required;
110	        int nationalLength;
111	        if (digits.startsWith("61")) {
112	            required = 9;
113	            nationalLength = digits.length() - 2;
114	        } else if (digits.startsWith("1")) {
115	            required = 10;
116	            nationalLength = digits.length() - 1;
117	        } else {
118	            return; // no length rule for this country code
119	        }
120	        if (nationalLength != required) {
121	            throw new InvalidTelephoneException(raw);
122	        }
123	    }
124	}
