194	==== EnsureUniqueIdentity ====
195	package org.springframework.samples.petclinic.rest.function.owner;
196	
197	import net.officefloor.plugin.variable.Val;
198	import org.springframework.samples.petclinic.model.Owner;
199	import org.springframework.samples.petclinic.repository.OwnerRepository;
200	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
201	import org.springframework.samples.petclinic.rest.escalation.DuplicateIdentityException;
202	
203	/**
204	 * The single duplicate-detection step in the create-owner pipeline, consolidating what used to be
205	 * separate telephone, email and household checks. Runs after the telephone and email are normalized
206	 * and after {@link DeriveHouseholdId} has resolved any shared {@code householdId}.
207	 *
208	 * <p>It applies two 409 rules against the already-stored owners:
209	 * <ul>
210	 * <li><b>Identity duplicate</b> — the request's {@code identityKey}, derived exactly as
211	 * {@link Owner#getIdentityKey()} does ({@code normalizedTelephone|email|householdId}, email and
212	 * householdId empty when absent), equals an existing owner's whole key. This always rejects, even
213	 * with {@code sharesHousehold}.</li>
214	 * <li><b>Household duplicate</b> — the request's computed {@code householdId} (from lastName and
215	 * postcode) matches an existing owner's. Because the household is keyed on {@code (lastName,
216	 * postcode)}, a second owner in that household is a duplicate <em>unless</em> it declares
217	 * {@code sharesHousehold}, which admits it as a member.</li>
218	 * </ul>
219	 */
220	public class EnsureUniqueIdentity {
221	
222	    public void service(@Val OwnerFieldsDto request, @Val HouseholdId householdId,
223	            OwnerRepository ownerRepository) throws DuplicateIdentityException {
224	        String householdIdValue = (householdId == null) ? null : householdId.value();
225	        String identityKey = identityKey(request, householdIdValue);
226	        boolean sharesHousehold = Boolean.TRUE.equals(request.getSharesHousehold());
227	        for (Owner existing : ownerRepository.findAll()) {
228	            if (identityKey.equals(existing.getIdentityKey())) {
229	                throw new DuplicateIdentityException(identityKey);
230	            }
231	            // A household of one (no postcode) shares with no one; sharesHousehold admits a member.
232	            if (!sharesHousehold && householdIdValue != null
233	                    && householdIdValue.equals(existing.getHouseholdId())) {
234	                throw new DuplicateIdentityException(householdIdValue);
235	            }
236	        }
237	    }
238	
239	    /** Derive the key for the owner being created, matching {@link Owner#getIdentityKey()} exactly. */
240	    private static String identityKey(OwnerFieldsDto request, String householdId) {
241	        String tel = request.getTelephone() == null ? "" : request.getTelephone();
242	        String email = request.getEmail();
243	        String mail = (email == null || email.isBlank()) ? "" : email;
244	        String household = (householdId == null || householdId.isBlank()) ? "" : householdId;
245	        return tel + "|" + mail + "|" + household;
246	    }
247	}
