339	
340	/**
341	 * Runs in the create-owner pipeline after {@link BuildOwner}. Validates the owner's postcode ONLY
342	 * when one is present: an absent (or blank) postcode is optional and accepted, keeping the request
343	 * contract backward-compatible. When present it must be exactly four digits and, when the owner's
344	 * city maps to a known region ({@link Owner#getLocality()}), fall within that region's inclusive
345	 * postcode range (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099). A city with no known region
346	 * ('UNKNOWN') accepts any 4-digit postcode. Anything else is rejected with a 400.
347	 */
348	public class ValidateOwnerPostcode {
349	
350	    /** Region -> inclusive 4-digit postcode range {low, high}. */
351	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
352	            "NSW", new int[] {2000, 2099},
353	            "VIC", new int[] {3000, 3099},
354	            "QLD", new int[] {4000, 4099});
355	
356	    public void service(@Val Owner owner) throws InvalidPostcodeException {
357	        String postcode = owner.getPostcode();
358	        if (postcode == null || postcode.isBlank()) {
359	            return; // optional when absent
360	        }
361	        if (!postcode.matches("[0-9]{4}")) {
362	            throw new InvalidPostcodeException(postcode);
363	        }
364	        int[] range = REGION_POSTCODES.get(owner.getLocality());
365	        if (range != null) {
366	            int value = Integer.parseInt(postcode);
367	            if (value < range[0] || value > range[1]) {
368	                throw new InvalidPostcodeException(postcode);
369	            }
370	        }
371	    }
372	}
