514	import java.nio.charset.StandardCharsets;
515	import java.security.MessageDigest;
516	import java.security.NoSuchAlgorithmException;
517	
518	import net.officefloor.plugin.variable.Val;
519	import org.springframework.samples.petclinic.model.Owner;
520	
521	/**
522	 * Runs in the create-owner pipeline before {@link SaveOwner}. Assigns the owner's
523	 * {@code customerCode}, formatted {@code '<REGION>-<HASH8>'} where REGION is the region code shared
524	 * with {@link Owner#getLocality()} (derived from the postcode, falling back to the city, else
525	 * {@code 'UNKNOWN'}) and HASH8 is the first eight upper-case hex characters of a SHA-256 digest over
526	 * the normalized telephone concatenated with the last name (e.g. 'NSW-1A2B3C4D'). The sequence
527	 * numbers of the former city-and-last-name format are gone. Mutates the built owner in place so
528	 * later steps (membership number, check digit, audit) derive from and store the assigned code.
529	 */
530	public class AssignCustomerCode {
531	
532	    public void service(@Val Owner owner) {
533	        String region = owner.getLocality();
534	        String hash8 = shaHex8(owner.getTelephone() + owner.getLastName());
535	        owner.setCustomerCode(region + "-" + hash8);
536	    }
537	
538	    /** First eight UPPER-case hex characters of SHA-256 over the UTF-8 bytes of {@code s}. */
539	    private static String shaHex8(String s) {
540	        try {
541	            byte[] digest = MessageDigest.getInstance("SHA-256")
542	                    .digest(s.getBytes(StandardCharsets.UTF_8));
543	            StringBuilder sb = new StringBuilder();
544	            for (byte b : digest) {
545	                sb.append(String.format("%02X", b));
546	                if (sb.length() >= 8) {
547	                    break;
548	                }
549	            }
550	            return sb.substring(0, 8);
551	        }
552	        catch (NoSuchAlgorithmException e) {
553	            throw new IllegalStateException("SHA-256 not available", e);
554	        }
555	    }
556	}
