615	package org.springframework.samples.petclinic.rest.function.owner;
616	
617	import net.officefloor.plugin.variable.Val;
618	import org.springframework.samples.petclinic.model.Owner;
619	import org.springframework.samples.petclinic.repository.OwnerRepository;
620	
621	/**
622	 * Soft-match step in the create-owner pipeline. Runs after {@link BuildOwner} (so the owner carries
623	 * its normalized telephone, lastName and postcode) and before {@link SaveOwner}. It is reached only
624	 * for owners that already passed {@link EnsureUniqueIdentity}, i.e. that are NOT hard duplicates.
625	 *
626	 * <p>An owner is a <em>possible</em> duplicate when an existing owner shares its {@code lastName}
627	 * and {@code postcode} but has a different {@code telephone}. When such an owner exists the new
628	 * owner is still created, but flagged with {@code possibleDuplicate = true} and
629	 * {@code possibleDuplicateOf} set to the matching owner's id (the lowest id when several match).
630	 * Otherwise {@code possibleDuplicate} is set to {@code false} and no match id is recorded.
631	 *
632	 * <p>An existing owner in the <em>same household</em> (same computed {@code householdId}) is never a
633	 * soft match: a second owner sharing lastName and postcode is either rejected as a household
634	 * duplicate ({@link EnsureUniqueIdentity}) or admitted as a declared member via
635	 * {@code sharesHousehold}, and a declared member is not a suspected duplicate.
636	 */
637	public class DetectPossibleDuplicate {
638	
639	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
640	        owner.setPossibleDuplicate(false);
641	        owner.setPossibleDuplicateOf(null);
642	
643	        String lastName = owner.getLastName();
644	        String postcode = owner.getPostcode();
645	        String telephone = owner.getTelephone();
646	        if (lastName == null || postcode == null || postcode.isBlank()) {
647	            return; // a shared lastName+postcode is required to be a possible duplicate
648	        }
649	
650	        Integer matchId = null;
651	        for (Owner existing : ownerRepository.findAll()) {
652	            if (existing.getId() == null) {
653	                continue;
654	            }
655	            if (lastName.equals(existing.getLastName())
656	                    && postcode.equals(existing.getPostcode())
657	                    && !sameHousehold(owner, existing)
658	                    && !equalsTelephone(telephone, existing.getTelephone())) {
659	                if (matchId == null || existing.getId() < matchId) {
660	                    matchId = existing.getId();
661	                }
662	            }
663	        }
664	
665	        if (matchId != null) {
666	            owner.setPossibleDuplicate(true);
667	            owner.setPossibleDuplicateOf(matchId);
668	        }
669	    }
670	
671	    private static boolean equalsTelephone(String a, String b) {
672	        return a == null ? b == null : a.equals(b);
673	    }
674	
675	    private static boolean sameHousehold(Owner a, Owner b) {
676	        return a.getHouseholdId() != null && a.getHouseholdId().equals(b.getHouseholdId());
677	    }
678	}
